package hospital.management.system;import java.sql.Connection;import java.sql.DriverManager;import java.sql.SQLException;import java.sql.Statement;public class conn {    private static final String DB_URL =            "jdbc:mysql://localhost:3306/hospital_management_system";    private static final String DB_USER = "root";    private static final String DB_PASSWORD_ENV =            "HMS_DB_PASSWORD";    public Connection connection;    public Statement statement;    public conn() {        try {            String password = System.getenv(DB_PASSWORD_ENV);            if (password == null || password.isBlank()) {                throw new IllegalStateException(                        "Database password is missing. " +                                "Please set the HMS_DB_PASSWORD environment variable."                );            }            connection = DriverManager.getConnection(                    DB_URL,                    DB_USER,                    password            );            statement = connection.createStatement();        } catch (SQLException e) {            throw new IllegalStateException(                    "Unable to connect to the hospital database. " +                            "Make sure MySQL is running and the database " +                            "'hospital_management_system' exists.",                    e            );        } catch (Exception e) {            throw new IllegalStateException(                    "Database configuration error: " + e.getMessage(),                    e            );        }    }    public void close() {        try {            if (statement != null && !statement.isClosed()) {                statement.close();            }            if (connection != null && !connection.isClosed()) {                connection.close();            }        } catch (SQLException e) {            e.printStackTrace();        }    }}